mkitem!{# [doc = " Raw file descriptors."] pub type RawFd = i32 ;}
mkitem!{type ValidRawFd = core :: num :: niche_types :: NotAllOnes < RawFd > ;}
mkitem!{mkstruct!{# [doc = " A borrowed SOLID Sockets file descriptor."] # [doc = ""] # [doc = " This has a lifetime parameter to tie it to the lifetime of something that"] # [doc = " owns the socket."] # [doc = ""] # [doc = " This uses `repr(transparent)` and has the representation of a host file"] # [doc = " descriptor, so it can be used in FFI in places where a socket is passed as"] # [doc = " an argument, it is not captured or consumed, and it never has the value"] # [doc = " `SOLID_NET_INVALID_FD`."] # [doc = ""] # [doc = " This type's `.to_owned()` implementation returns another `BorrowedFd`"] # [doc = " rather than an `OwnedFd`. It just makes a trivial copy of the raw"] # [doc = " socket, which is then borrowed under the same lifetime."] # [derive (Copy , Clone)] # [repr (transparent)] # [rustc_nonnull_optimization_guaranteed] pub struct BorrowedFd < 'socket > { fd : ValidRawFd , _phantom : PhantomData < & 'socket OwnedFd > , }}}
mkitem!{mkstruct!{# [doc = " An owned SOLID Sockets file descriptor."] # [doc = ""] # [doc = " This closes the file descriptor on drop."] # [doc = ""] # [doc = " This uses `repr(transparent)` and has the representation of a host file"] # [doc = " descriptor, so it can be used in FFI in places where a socket is passed as"] # [doc = " an argument, it is not captured or consumed, and it never has the value"] # [doc = " `SOLID_NET_INVALID_FD`."] # [repr (transparent)] # [rustc_nonnull_optimization_guaranteed] pub struct OwnedFd { fd : ValidRawFd , }}}
mkitem!{mkimpl!{impl BorrowedFd < '_ > { # [doc = " Returns a `BorrowedFd` holding the given raw file descriptor."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The resource pointed to by `fd` must remain open for the duration of"] # [doc = " the returned `BorrowedFd`, and it must not have the value"] # [doc = " `SOLID_NET_INVALID_FD`."] # [inline] # [track_caller] pub const unsafe fn borrow_raw (fd : RawFd) -> Self { Self { fd : ValidRawFd :: new (fd) . expect ("fd != -1") , _phantom : PhantomData } } }}}
mkitem!{mkimpl!{impl OwnedFd { # [doc = " Creates a new `OwnedFd` instance that shares the same underlying file"] # [doc = " description as the existing `OwnedFd` instance."] pub fn try_clone (& self) -> crate :: io :: Result < Self > { self . as_fd () . try_clone_to_owned () } }}}
mkitem!{mkimpl!{impl BorrowedFd < '_ > { # [doc = " Creates a new `OwnedFd` instance that shares the same underlying file"] # [doc = " description as the existing `BorrowedFd` instance."] pub fn try_clone_to_owned (& self) -> crate :: io :: Result < OwnedFd > { let fd = sys :: net :: cvt (unsafe { crate :: sys :: abi :: sockets :: dup (self . as_raw_fd ()) }) ? ; Ok (unsafe { OwnedFd :: from_raw_fd (fd) }) } }}}
