mkitem!{mkimpl!{impl IntoRawFd for OwnedFd { # [inline] fn into_raw_fd (self) -> RawFd { ManuallyDrop :: new (self) . fd . as_inner () } }}}
mkitem!{mkimpl!{impl FromRawFd for OwnedFd { # [doc = " Constructs a new instance of `Self` from the given raw file descriptor."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The resource pointed to by `fd` must be open and suitable for assuming"] # [doc = " ownership. The resource must not require any cleanup other than `close`."] # [inline] # [track_caller] unsafe fn from_raw_fd (fd : RawFd) -> Self { Self { fd : ValidRawFd :: new (fd) . expect ("fd != -1") } } }}}
mkitem!{mkimpl!{impl Drop for OwnedFd { # [inline] fn drop (& mut self) { unsafe { crate :: sys :: abi :: sockets :: close (self . fd . as_inner ()) } ; } }}}
