mkitem!{mkimpl!{impl fmt :: Debug for OwnedFd { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("OwnedFd") . field ("fd" , & self . fd) . finish () } }}}
