mkitem!{mktrait!{# [doc = " A trait to extract the raw SOLID Sockets file descriptor from an underlying"] # [doc = " object."] pub trait AsRawFd { # [doc = " Extracts the raw file descriptor."] # [doc = ""] # [doc = " This method does **not** pass ownership of the raw file descriptor"] # [doc = " to the caller. The descriptor is only guaranteed to be valid while"] # [doc = " the original object has not yet been destroyed."] fn as_raw_fd (& self) -> RawFd ; }}}
mkitem!{mktrait!{# [doc = " A trait to express the ability to construct an object from a raw file"] # [doc = " descriptor."] pub trait FromRawFd { # [doc = " Constructs a new instance of `Self` from the given raw file"] # [doc = " descriptor."] # [doc = ""] # [doc = " This function is typically used to **consume ownership** of the"] # [doc = " specified file descriptor. When used in this way, the returned object"] # [doc = " will take responsibility for closing it when the object goes out of"] # [doc = " scope."] # [doc = ""] # [doc = " However, consuming ownership is not strictly required. Use a"] # [doc = " [`From<OwnedFd>::from`] implementation for an API which strictly"] # [doc = " consumes ownership."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The `fd` passed in must be an [owned file descriptor][io-safety];"] # [doc = " in particular, it must be open."] # [doc = ""] # [doc = " [io-safety]: io#io-safety"] unsafe fn from_raw_fd (fd : RawFd) -> Self ; }}}
mkitem!{mktrait!{# [doc = " A trait to express the ability to consume an object and acquire ownership of"] # [doc = " its raw file descriptor."] pub trait IntoRawFd { # [doc = " Consumes this object, returning the raw underlying file descriptor."] # [doc = ""] # [doc = " This function **transfers ownership** of the underlying file descriptor"] # [doc = " to the caller. Callers are then the unique owners of the file descriptor"] # [doc = " and must close the descriptor once it's no longer needed."] # [must_use = "losing the raw file descriptor may leak resources"] fn into_raw_fd (self) -> RawFd ; }}}
